CREATE ROLE anon; CREATE ROLE authenticated; CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
CREATE TYPE app_role AS ENUM('master','auftraggeber','durchfuehrer');
CREATE TABLE user_roles(user_id uuid,role app_role);
CREATE FUNCTION has_role(u uuid,r app_role) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=u AND role=r) $$;
CREATE FUNCTION is_external_customer(u uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT current_setting('test.external',true)='true' $$;
CREATE FUNCTION _order_lock_bypass() RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE TABLE measurement_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_by uuid,status text DEFAULT 'open',order_type text DEFAULT 'customer',workflow_status text DEFAULT 'entwurf',project_id uuid,order_number text,shared_form_data jsonb DEFAULT '{}');
CREATE FUNCTION is_order_locked(u uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce((SELECT workflow_status='abgeschlossen' FROM measurement_orders WHERE id=u),false) $$;
CREATE TABLE order_measurements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE,assigned_to uuid,status text DEFAULT 'open',actual_duration_hours numeric,source_measurement_id uuid REFERENCES order_measurements ON DELETE SET NULL);
CREATE TABLE activity_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_type text,actor_user_id uuid,order_id uuid REFERENCES measurement_orders ON DELETE CASCADE,order_measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE,project_id uuid,metadata jsonb DEFAULT '{}');
CREATE TABLE order_audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE,field_name text);
CREATE TABLE workflow_calls(id uuid);
CREATE FUNCTION recompute_order_workflow_status(u uuid) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM measurement_orders WHERE id=u) THEN RAISE EXCEPTION 'missing parent workflow'; END IF; INSERT INTO workflow_calls VALUES(u); END $$;
CREATE TABLE measurement_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE);
CREATE TABLE measurement_raw_datasets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE);
CREATE TABLE measurement_result_corrections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE,order_id uuid);
CREATE TABLE measurement_import_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE);
CREATE TABLE work_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE);
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE);
CREATE TABLE measurement_parameters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE);
ALTER TABLE measurement_results ADD COLUMN is_official boolean DEFAULT false;
CREATE TABLE order_workflow_instances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE);
CREATE TABLE order_samples(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE);
CREATE TABLE order_analysis_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE);
CREATE TABLE order_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE);
CREATE TABLE pilot_plant_produced_samples(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE);
CREATE TABLE production_document_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE);
CREATE TABLE project_time_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE SET NULL);
CREATE TABLE production_releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE SET NULL);
CREATE TABLE project_knetung_materials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_measurement_id uuid REFERENCES order_measurements ON DELETE SET NULL);
CREATE TABLE order_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_order_id uuid REFERENCES measurement_orders ON DELETE SET NULL);
CREATE TABLE samples(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE SET NULL,pilot_plant_order_id uuid REFERENCES measurement_orders ON DELETE SET NULL,prepared_for_measurement_id uuid REFERENCES order_measurements ON DELETE SET NULL);
CREATE TABLE order_upload_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),measurement_id uuid REFERENCES order_measurements ON DELETE CASCADE);
CREATE TABLE order_processes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE,status text DEFAULT 'pending',completed_at timestamptz,started_at timestamptz);
CREATE TABLE order_process_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_process_id uuid REFERENCES order_processes ON DELETE CASCADE,status text DEFAULT 'pending',completed_at timestamptz,started_at timestamptz);
CREATE TABLE order_service_forms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_process_service_id uuid REFERENCES order_process_services ON DELETE CASCADE,status text DEFAULT 'pending',completed_at timestamptz,response_data jsonb);
CREATE TABLE order_workflow_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE,status text DEFAULT 'pending',completed_at timestamptz,opened_at timestamptz,time_entry_id uuid,auto_time_minutes int,form_response jsonb);
CREATE TABLE order_instances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),legacy_order_id uuid,status text DEFAULT 'draft');
CREATE TABLE order_form_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid,version int);
CREATE TABLE order_step_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES order_instances ON DELETE CASCADE,status text DEFAULT 'pending',completed_at timestamptz,opened_at timestamptz,time_entry_id uuid,auto_time_minutes int,form_response jsonb);
ALTER TABLE order_workflow_tasks ADD COLUMN instance_id uuid REFERENCES order_workflow_instances ON DELETE CASCADE;
CREATE TABLE order_step_positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),step_run_id uuid REFERENCES order_step_runs ON DELETE CASCADE,status text DEFAULT 'open',completed_at timestamptz,result_value text,result_data jsonb);
CREATE TABLE order_workflow_task_positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid REFERENCES order_workflow_tasks ON DELETE CASCADE,status text DEFAULT 'open',completed_at timestamptz,result_value text,result_data jsonb);
CREATE TABLE pilot_plant_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES measurement_orders ON DELETE CASCADE,status text DEFAULT 'pending',completed_at timestamptz,started_at timestamptz);
GRANT USAGE ON SCHEMA public,auth TO authenticated; GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
ALTER TABLE measurement_orders ENABLE ROW LEVEL SECURITY; CREATE POLICY fixture_owner ON measurement_orders TO authenticated USING (created_by=auth.uid());
